package ama.transcript;
import ama.config.ConfigArchiveSource;import ama.contract.IdentityContracts.Actor;import ama.contract.MinutesContracts.*;import ama.contract.TaskContracts.SubjectRef;import java.util.*;import java.util.function.Supplier;import org.springframework.jdbc.core.JdbcTemplate;import static ama.contract.MinutesContracts.*;import static ama.contract.MinutesContracts.FailureCode.*;
/** Controlled actual S/A/F composition; formal new effects await the combined publication installation. */
public final class JdbcMinutesSavedCommands {
 private final JdbcTranscriptAuthority authority;private final Supplier<ConfigArchiveSource.Snapshot> archives;private final String pin;private final TranscriptAcquisitionBudget limits;private final JdbcMinutesCommandReceipts receipts;private final JdbcTemplate j;
 public JdbcMinutesSavedCommands(JdbcTranscriptAuthority authority,Supplier<ConfigArchiveSource.Snapshot> archives,String pin,TranscriptAcquisitionBudget limits){this.authority=Objects.requireNonNull(authority);this.archives=Objects.requireNonNull(archives);hash(pin);this.pin=pin;this.limits=Objects.requireNonNull(limits);receipts=new JdbcMinutesCommandReceipts(authority.dataSource(),authority.transactionRunner(),authority.savedAccess());j=new JdbcTemplate(authority.dataSource());j.setQueryTimeout(2);}
 private record AdoptPlan(MinutesGraphCapture.Graph graph,MinutesSavedGraphPlan copy,String candidate,String input,String fingerprint){}
 public Map<String,Object> adopt(Actor actor,String meeting,String key,long expected,String candidate,String input,String fingerprint,String trace){
  JdbcMinutesFactsReader.independent();uuid(candidate);uuid(input);uuid(trace);hash(fingerprint);var identity=JdbcMinutesCommandReceipts.identity(actor,meeting,"MINUTES_ADOPT",key,expected,candidate,input,fingerprint);var replay=receipts.lookup(actor,meeting,identity);if(replay.isPresent())return replay.orElseThrow();
  var budget=limits.ledger(authority.readBudget(),authority.canonicalBudget(),()->false);MinutesGraphDiscovery.Discovery declaration=null;MinutesGraphCapture.Graph captured=null;AdoptPlan planned=null;RuntimeException error=null;
  try{declaration=MinutesGraphDiscovery.withPending(authority.dataSource(),MinutesGraphDiscovery.discover(authority.dataSource(),meeting,"ADOPT",candidate,limits,authority.readBudget()),limits.tasks());JdbcMinutesFactsReader.charge(declaration,budget);var declared=declaration;captured=authority.transactionRunner().required(()->{var gate=JdbcMinutesFactsReader.lockGraph(authority,actor,meeting,declared);var scope=authority.minutesScope(gate,actor,meeting);var graph=MinutesGraphCapture.captureCurrent(authority,scope,gate,actor,declared,budget);adoptable(graph,expected,candidate,input,fingerprint);return graph;});
   new JdbcMinutesFactsReader(authority,archives,pin,limits).prepare(captured,budget);var original=candidate(captured,candidate);var copy=MinutesSavedGraphPlan.copy((String)original.get("minutes_revision_id"),(String)original.get("element_set_id"),captured.rows(),(String)captured.discovery().root().get("minutes_revision_id"),actor.enterpriseId(),budget).protectHumanTitle(captured);planned=new AdoptPlan(captured,copy,candidate,input,fingerprint);
  }catch(RuntimeException failure){if(Thread.currentThread().isInterrupted()||failure instanceof Failure f&&f.code()==CANCELLED)throw failure;error=failure;}
  final var selected=declaration;final var plan=planned;final var failed=error;
  return authority.transactionRunner().required(()->{var stored=receipts.claim(actor,meeting,identity);var gate=JdbcMinutesFactsReader.lockGraph(authority,actor,meeting,selected);JdbcMinutesCommandReceipts.match(stored);if(stored.result()!=null)return receipts.restore(meeting,identity,stored,true);if(failed!=null)throw failed;
   var scope=authority.minutesScope(gate,actor,meeting);var fresh=MinutesGraphCapture.captureCurrent(authority,scope,gate,actor,selected,budget);require(fresh.equals(plan.graph()),PROVENANCE_UNAVAILABLE);adoptable(fresh,expected,candidate,input,fingerprint);authority.claimMinutesWrite(scope,gate,actor,fresh,JdbcTranscriptAuthority.MinutesWritePurpose.ADOPT,plan,candidate);
   var writer=new MinutesSavedWriter(authority);writer.writeAndReadback(scope,gate,actor,fresh,JdbcTranscriptAuthority.MinutesWritePurpose.ADOPT,plan,plan.copy().rows(MinutesHistorySlots.next(fresh,"minutes_revision",1),MinutesHistorySlots.next(fresh,"element_set",1)),plan.copy(),budget);
   require(j.update("UPDATE generation_candidate SET state='ADOPTED',decided_at=UTC_TIMESTAMP(6) WHERE id=? AND meeting_id=? AND state='PENDING' AND base_revision=?",candidate,meeting,expected)==1,PROVENANCE_UNAVAILABLE);writer.advance(scope,gate,actor,fresh,plan.copy(),fingerprint,expected+1);receipts.accepted(identity,candidate);var response=receipts.restore(meeting,identity,new JdbcMinutesCommandReceipts.Stored(candidate,200,true),false);
   new ama.audit.JdbcAuditAdapter(authority.dataSource()).append(new ama.contract.AuditContracts.AuditEvent(actor.enterpriseId(),"MINUTES_ADOPTED",meeting,expected+1,"SUCCEEDED",trace,java.time.Instant.now()));var outbox=new ama.task.JdbcOutbox(authority.dataSource(),new MinutesEventReferences(authority.dataSource()).validators());outbox.append(new ama.contract.OutboxContracts.EventDraft("MINUTES_ADOPTED",null,new SubjectRef("MEETING",meeting),expected+1,new ama.contract.OutboxContracts.Reference("MINUTES_REVISION",plan.copy().body())));outbox.flush();return response;
  });
 }
 private static Map<String,Object> candidate(MinutesGraphCapture.Graph graph,String id){var found=graph.auxiliary().getOrDefault("generation_candidate",List.of()).stream().filter(row->id.equals(row.get("id"))).toList();require(found.size()==1,PROVENANCE_UNAVAILABLE);return found.getFirst();}
 private static void adoptable(MinutesGraphCapture.Graph graph,long expected,String id,String inputId,String fingerprint){var root=graph.discovery().root();JdbcMinutesGenerationPreparation.writable(root,expected);if(expected>=Long.MAX_VALUE-1)throw new ama.contract.TranscriptContracts.Failure(409,"REVISION_EXHAUSTED");var c=candidate(graph,id);if(!"PENDING".equals(c.get("state"))||((Number)c.get("base_revision")).longValue()!=expected)throw new ama.contract.TranscriptContracts.Failure(409,"CANDIDATE_NOT_CURRENT");require(inputId.equals(c.get("input_id"))&&fingerprint.equals(c.get("input_fingerprint")),PROVENANCE_UNAVAILABLE);var input=JdbcMinutesFactsReader.one(graph,Table.GENERATION_INPUT,inputId);for(String key:List.of("transcript_confirmation_id","template_revision_id","exclusion_revision_id","element_set_id"))require(Objects.equals(input.nullableString(key),root.get(key)),PROVENANCE_UNAVAILABLE);var tasks=graph.auxiliary().getOrDefault("durable_task",List.of()).stream().filter(row->c.get("task_id").equals(row.get("id"))).toList();require(tasks.size()==1,PROVENANCE_UNAVAILABLE);var task=tasks.getFirst();require("SUCCEEDED".equals(task.get("state"))&&"GENERATION_CANDIDATE".equals(task.get("output_kind"))&&id.equals(task.get("output_id"))&&inputId.equals(task.get("input_id"))&&fingerprint.equals(task.get("input_fingerprint"))&&((Number)task.get("business_version")).longValue()==expected&&Objects.equals(task.get("cancel_epoch"),root.get("cancel_epoch")),PROVENANCE_UNAVAILABLE);}
}
